<template><section class="card p-4 mt-5"><h2 class="section-title">{{parent?'Аннулированные оплаты':'Платежи и исправления'}}</h2><div v-for="p in visible" :key="p.id" class="py-3 border-b border-line"><p>{{childById(p.child_id)?.name}} · {{formatMoney(p.amount_minor/100)}} · {{labels[p.status]||p.status}} {{p.method==='test'?'· Тестовая оплата':''}}</p><p v-if="p.void_reason" class="text-xs text-muted">{{p.void_reason}}</p><template v-if="!parent"><button v-if="p.status==='succeeded'&&['cash','transfer','test'].includes(p.method)" class="btn-quiet text-clay" :disabled="busy" @click="voidPayment(p)">Аннулировать оплату</button><button v-if="p.receipt" class="btn-quiet" :disabled="busy" @click="removeReceipt(p)">Удалить неверный чек</button></template></div><p v-if="!visible.length" class="text-sm text-muted mt-3">Нет записей.</p></section></template>
<script setup lang="ts">import {computed,ref} from 'vue';import {api,key} from '../shared/api';import {serverPayments,useDemo,refresh} from '../shared/use-demo';import {formatMoney} from '../shared/demo';const props=defineProps<{parent?:boolean}>();const {childById}=useDemo();const busy=ref(false),keys=new Map<string,string>();const labels:Record<string,string>={succeeded:'Оплачен',voided:'Аннулирован',pending:'Ожидает оплаты',canceled:'Отменён'};const visible=computed(()=>serverPayments.value.filter(p=>props.parent?p.status==='voided':['succeeded','voided'].includes(p.status)));async function voidPayment(p:any){const reason=prompt('Причина аннулирования. Счёт станет неоплаченным; история посещений и записи сохранятся.');if(!reason?.trim())return;if(!confirm('Аннулировать эту оплату?'))return;busy.value=true;try{const k=keys.get(p.id)||key();keys.set(p.id,k);await api('/master/payments/'+p.id+'/void','POST',{reason,expected_version:p.version},k);await refresh();}finally{busy.value=false;}}async function removeReceipt(p:any){if(!confirm('Удалить неверно прикреплённый чек? Он перестанет быть доступен родителю; история сохранится.'))return;busy.value=true;try{const r=await api('/receipts/'+p.receipt.id);await api('/master/receipts/'+r.id,'DELETE',{reason:'Ошибочно прикреплённый чек',expected_version:r.version});await refresh();}finally{busy.value=false;}}</script>
